for i, (a, b) in enumerate(P):
    if a in s:
        s = s.replace(a, b, 1)
    elif b in s or i < OPTIONAL:
        print('patch', i, 'already applied or skipped')
    else:
        raise SystemExit('patch %d anchor missing: %r' % (i, a[:80]))
exec(compile(s, base, 'exec'), {'__file__': base, '__name__': '__main__'})
